WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_reading_sentence'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '句子理解', 'kp-sl-reading-sentence', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "句子理解：剥离修饰语"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "把又长又臭的领导讲话或公文长句，压缩成主谓宾的骨架。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、阅读拆解"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "申论材料里有一句话：“为了进一步深化农业供给侧结构性改革，加快培育农村发展新动能，该县大力推进了以休闲观光农业为龙头的田园综合体建设。”"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这句话的核心是什么？"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“为了...”是目的，不是动作本身，略读。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“该县”是主语，“大力推进了”是谓语，“田园综合体建设”是宾语。中间的“以休闲观光农业为龙头的”是修饰语。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "缩句结果：推进田园综合体建设。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、实战运用"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在字数极度受限（如要求 100 字内概括）的题目中，必须毫不留情地删掉所有的形容词、副词、程度词。只保留动词和名词。"}]}]}$$ AS jsonb), NULL, '句子理解的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "阅读理解", "缩句法"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_reading_sentence", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
